代码示例： import UIKit import RxSwift let ScreenW = UIScreen.main.bounds.size.width let statusBarH = UIApplication.shared.statusBarFrame.size.height class AccountHeaderView: UIView { var disposeBag = DisposeBag() lazy var panoView : UIImageView = { let imgView = UIImageView() imgView.image = UIImage(named: &#34;avator&#34;) imgView.contentMode = .scaleAspectFill imgView.clipsToBounds = true return imgView }() var bgImgFrame: CGRect // 展示其他信息 var infoView: UIView? lazy var backPanoView : UIView = { let view = UIView() return view }() override init(frame:CGRect) { self.bgImgFrame = CGRect(x: 0, y: 0, width: ScreenW, height: 200) super.init(frame: frame) self.addSubview(backPanoView) self.backPanoView.addSubview(panoView) // 展示其他信息 self.infoView = UIView() self.addSubview(infoView!) self.backPanoView.frame = self.bgImgFrame } override func layoutSubviews() { super.layoutSubviews() self.panoView.snp.makeConstraints { (make) in make.edges.equalToSuperview() } self.infoView?.snp.makeConstraints { (make) in make.top.equalToSuperview().offset(200) make.left.right.equalToSuperview() make.bottom.equalToSuperview() } } required init?(coder aDecoder: NSCoder) { fatalError(&#34;init(coder:) has not been implemented&#34;) } func scrollVieDidScroll(offsetY: CGFloat) { // 在tableview滑动过程中重新这只backPanoView 的frame if offsetY &lt;= 0{ var rect = self.backPanoView.frame rect.origin.y = offsetY rect.size.height = 200 - offsetY self.backPanoView.frame = rect self.panoView.setNeedsLayout() } } }

